-- JARVIS Approval Center — proposed SQL release script, REVIEW ONLY.
--
-- DO NOT execute as part of CI or directly against production.
-- Required release order: merge/test Supabase backend-auth PR #37, validate
-- current server-side create/readback flows, verify privileged service_role,
-- freeze writes, stage this exact script, then obtain explicit SQL approval.
-- Review tenant-aware end-user access paths before removing client grants.
-- Tracked in GitHub issue #52.
--
-- This is NOT a Supabase migration generated by the CLI and is deliberately
-- excluded from supabase/migrations; use a reviewed CLI migration at release.

BEGIN;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '15s';

DO $approval_preflight$
DECLARE
  candidate text;
BEGIN
  FOREACH candidate IN ARRAY ARRAY['approval_decision','approval_request','approval_audit_log']
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname = candidate
        AND c.relkind IN ('r', 'p') AND c.relrowsecurity
    ) THEN
      RAISE EXCEPTION 'Approval Center schema or RLS preflight failed on %', candidate;
    END IF;
    IF NOT has_table_privilege('service_role', format('public.%I', candidate), 'SELECT')
      OR NOT has_table_privilege('service_role', format('public.%I', candidate), 'INSERT')
      OR NOT has_table_privilege('service_role', format('public.%I', candidate), 'UPDATE')
    THEN
      RAISE EXCEPTION 'Service-side access preflight failed on %', candidate;
    END IF;
  END LOOP;
END;
$approval_preflight$;

-- Service-role grants survive; reject all direct anonymous and signed-in
-- table writes until reviewed owner/tenant-authorized APIs replace them.
REVOKE ALL PRIVILEGES ON TABLE public.approval_decision FROM PUBLIC, anon, authenticated;
REVOKE ALL PRIVILEGES ON TABLE public.approval_request FROM PUBLIC, anon, authenticated;
REVOKE ALL PRIVILEGES ON TABLE public.approval_audit_log FROM PUBLIC, anon, authenticated;

-- Remove misleading legacy policies, not just privileges.
DROP POLICY IF EXISTS jarvis_anon_tenant_insert ON public.approval_decision;
DROP POLICY IF EXISTS jarvis_anon_tenant_select ON public.approval_decision;
DROP POLICY IF EXISTS jarvis_anon_tenant_update ON public.approval_decision;
DROP POLICY IF EXISTS jarvis_backend_insert_pending ON public.approval_decision;
DROP POLICY IF EXISTS jarvis_backend_insert_request ON public.approval_request;
DROP POLICY IF EXISTS jarvis_backend_insert_audit ON public.approval_audit_log;

-- Assert no privileges remain for untrusted API roles.
DO $approval_verify$
DECLARE
  candidate text;
  role_name text;
  privilege_name text;
BEGIN
  FOREACH candidate IN ARRAY ARRAY['approval_decision','approval_request','approval_audit_log']
  LOOP
    FOREACH role_name IN ARRAY ARRAY['anon','authenticated']
    LOOP
      FOREACH privilege_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE']
      LOOP
        IF has_table_privilege(role_name, format('public.%I', candidate), privilege_name)
        THEN
          RAISE EXCEPTION 'Unexpected % privilege for % on %',
            privilege_name, role_name, candidate;
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
END;
$approval_verify$;

COMMIT;

